select 'roles' as entity,count(*) as count from public.roles union all select 'permissions',count(*) from public.permissions union all select 'features',count(*) from public.feature_registry union all select 'role_permissions',count(*) from public.role_permissions union all select 'role_features',count(*) from public.role_features union all select 'campuses',count(*) from public.campuses union all select 'departments',count(*) from public.departments union all select 'programs',count(*) from public.programs union all select 'user_roles',count(*) from public.user_roles order by entity;
